from pathlib import Path
import hashlib,sys
src=Path(sys.argv[1]).read_bytes()
assert hashlib.sha256(src).hexdigest()=="068d9b336fa3185372d9765b1f8c8983a7b39ee929b21c80ec6278378ee20393"
buf=bytearray(src)
buf[82034:82034]=b'J'
buf[69067:80674]=b''
buf[28227:28227]=b''
out=bytes(buf)
assert hashlib.sha256(out).hexdigest()=="2aa0bc1c5d60e6c81f17d917feb0c7cd7be7b4fbdf550d8987e8d3158885fe7c"
Path(sys.argv[2]).write_bytes(out)
